1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	import java.util.Objects;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Enforces email uniqueness: an owner's email (compared case-insensitively / lower-cased)
10	 * may not already belong to any other owner.
11	 */
12	final class DuplicateEmails {
13	
14	    private DuplicateEmails() {
15	    }
16	
17	    /**
18	     * Returns {@code true} when {@code candidate}'s email is already used by one of the
19	     * {@code existing} owners, comparing lower-cased (case-insensitively). A {@code null}
20	     * candidate email is never a duplicate.
21	     */
22	    static boolean isTaken(Owner candidate, Collection<Owner> existing) {
23	        String email = candidate.getEmail();
24	        if (email == null) {
25	            return false;
26	        }
27	        return existing.stream()
28	            .map(Owner::getEmail)
29	            .filter(Objects::nonNull)
30	            .anyMatch(email::equalsIgnoreCase);
31	    }
32	}
